INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21GBB0W', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $h$ is defined by $h(x) = -3x + 10$. What is the value of $h(-2)$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$6$"},{"key":"C","text":"$16$"},{"key":"D","text":"$-4$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = -2$: $h(-2) = -3(-2) + 10 = 6 + 10 = 16$. The value $4$ results from computing $-3(-2)$ as $-6$ instead of $6$, a sign error with the double negative, giving $-6 + 10 = 4$. The value $6$ comes from correctly computing $-3(-2) = 6$ but stopping without adding $10$, returning only the partial product. The value $-4$ results from computing $-3(2) - 10 = -16$ through multiple sign errors and then reporting $-4$ from further miscalculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22FTOBG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $JKL$, the right angle is at $K$. If $JK = 12$ and $\\sin(J) = \\frac{5}{13}$, what is the length of $KL$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$\\frac{60}{13}$"},{"key":"C","text":"$13$"},{"key":"D","text":"$\\frac{156}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'In right triangle $JKL$ with the right angle at $K$, $\\sin(J) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{KL}{JL}$. Since $\\sin(J) = \\frac{5}{13}$, the triangle has sides in the ratio $5:12:13$. Given $JK = 12$ (the side adjacent to angle $J$), the hypotenuse $JL = 13$ and the side opposite angle $J$ is $KL = 5$. The answer $\\frac{60}{13}$ results from setting up $\\sin(J) = \\frac{KL}{JK}$ and solving $\\frac{5}{13} = \\frac{KL}{12}$, mistakenly using the adjacent side as the hypotenuse. The answer $13$ is the hypotenuse, not the requested side. The answer $\\frac{156}{5}$ comes from inverting the sine ratio and multiplying by $12$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22IQVLR', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which inequality represents all values of $x$ such that $3x - 7 \\geq 5$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\geq 4$"},{"key":"B","text":"$x \\leq 4$"},{"key":"C","text":"$x \\geq -4$"},{"key":"D","text":"$x \\geq \\frac{5}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Add $7$ to both sides of $3x - 7 \\geq 5$ to get $3x \\geq 12$, then divide both sides by $3$ to obtain $x \\geq 4$. The result $x \\leq 4$ incorrectly reverses the inequality direction when dividing by a positive number. The result $x \\geq -4$ comes from a sign error when adding $7$ to $5$. The result $x \\geq \\frac{5}{3}$ comes from dividing $5$ by $3$ without first adding $7$ to both sides, skipping the subtraction step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22URMZ6', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f(x) = 3^x$ is defined for all real numbers. What is the value of $f(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$81$"},{"key":"C","text":"$64$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting gives $f(4) = 3^4 = 3 \\times 3 \\times 3 \\times 3 = 81$. The value $12$ results from computing $3 \\times 4$ instead of $3^4$, confusing exponentiation with multiplication. The value $64$ comes from computing $4^3$ instead of $3^4$, reversing the base and exponent. The value $7$ results from computing $3 + 4$ instead of $3^4$, confusing exponentiation with addition.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23NGRLF', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{2x^2 + 7x + 3}{2x^2 - 5x - 3}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x + 3}{x - 3}$"},{"key":"B","text":"$\\frac{2x + 3}{2x - 3}$"},{"key":"C","text":"$-1$"},{"key":"D","text":"$\\frac{x + 3}{x + 1}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the numerator: $2x^2 + 7x + 3 = (2x + 1)(x + 3)$. Factor the denominator: $2x^2 - 5x - 3 = (2x + 1)(x - 3)$. Canceling the common factor $(2x + 1)$ yields $\\frac{x + 3}{x - 3}$. The expression $\\frac{2x + 3}{2x - 3}$ results from attempting to split each trinomial by grouping the first two terms and the constant without proper factoring. The value $-1$ comes from the misconception that since the leading terms are identical and the constants $3$ and $-3$ are negatives, the fraction simplifies to $-1$. The expression $\\frac{x + 3}{x + 1}$ results from a sign error when factoring the denominator, producing $(2x - 3)(x + 1)$ instead of $(2x + 1)(x - 3)$ and then incorrectly canceling.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23QM9A9', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A student earns $\\$12$ per hour tutoring and $\\$9$ per hour working at a bookstore. The student must earn at least $\\$300$ per week but can work no more than $30$ hours total. If $t$ represents tutoring hours and $b$ represents bookstore hours, which system of inequalities models this situation?', NULL, $lyceon_json$[{"key":"A","text":"$12t + 9b \\geq 300$ and $t + b \\leq 30$"},{"key":"B","text":"$12t + 9b \\leq 300$ and $t + b \\leq 30$"},{"key":"C","text":"$9t + 12b \\geq 300$ and $t + b \\leq 30$"},{"key":"D","text":"$12t + 9b \\geq 300$ and $t + b \\geq 30$"}]$lyceon_json$::jsonb, 'A', NULL, E'Tutoring pays $\\$12$ per hour so tutoring earnings are $12t$, and the bookstore pays $\\$9$ per hour so bookstore earnings are $9b$. The student needs at least $\\$300$, giving $12t + 9b \\geq 300$. The student can work no more than $30$ hours total, giving $t + b \\leq 30$. Using $\\leq 300$ for the earnings constraint would model spending at most $\\$300$ rather than earning at least that amount. Swapping the pay rates so that $9$ multiplies $t$ and $12$ multiplies $b$ assigns each rate to the wrong job. Using $t + b \\geq 30$ reverses the hours constraint, requiring the student to work at least $30$ hours rather than at most $30$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23ZJ6ET', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(-1, 4)$ and $(3, -8)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -1)$"},{"key":"B","text":"$(0, 1)$"},{"key":"C","text":"$(0, 7)$"},{"key":"D","text":"$(0, -2)$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $\\frac{-8 - 4}{3 - (-1)} = \\frac{-12}{4} = -3$. Using point-slope form with $(-1, 4)$: $y - 4 = -3(x + 1)$, which gives $y = -3x - 3 + 4 = -3x + 1$. The $y$-intercept is $(0, 1)$. The intercept $(0, -1)$ results from a sign error when simplifying $-3 + 4$, obtaining $-1$ instead of $1$. The intercept $(0, 7)$ comes from computing $y - 4 = -3(x - 1)$ instead of $y - 4 = -3(x + 1)$, mishandling the sign of the $x$-coordinate, which gives $y = -3x + 3 + 4 = -3x + 7$. The intercept $(0, -2)$ comes from averaging the two $y$-coordinates $\\frac{4 + (-8)}{2} = -2$ instead of determining the equation of the line, confusing the midpoint with the intercept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24XP9K7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'A ladder leans against a vertical wall, making an angle of $60°$ with the ground. The foot of the ladder is $4$ meters from the base of the wall. What is the length of the ladder, in meters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Let $L$ be the length of the ladder. The ladder, the wall, and the ground form a right triangle. The angle between the ladder and the ground is $60°$, and the adjacent side (distance from wall) is $4$ m. Using $\\cos(60°) = \\frac{4}{L}$, and since $\\cos(60°) = \\frac{1}{2}$, we get $\\frac{1}{2} = \\frac{4}{L}$, so $L = 8$ meters. A common error is using $\\sin(60°)$ instead of $\\cos(60°)$, which would give $L = \\frac{4}{\\sin(60°)} = \\frac{8}{\\sqrt{3}} \\approx 4.62$, an incorrect result. Another error is using $\\tan(60°) = \\frac{4}{L}$, confusing the trigonometric ratios.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24YLLJ3', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'Which of the following is the slope of the line represented by the equation $3x + 6y = 18$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{1}{2}$"},{"key":"B","text":"$\\frac{1}{2}$"},{"key":"C","text":"$3$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting $3x + 6y = 18$ in slope-intercept form: subtract $3x$ from both sides to get $6y = -3x + 18$, then divide every term by $6$ to get $y = -\\frac{1}{2}x + 3$. The slope is $-\\frac{1}{2}$. The value $\\frac{1}{2}$ results from dropping the negative sign when dividing $-3$ by $6$. The value $3$ comes from reading the coefficient of $x$ in the original standard-form equation as the slope without converting to slope-intercept form. The value $6$ comes from reading the coefficient of $y$ in the original equation as the slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25ZSAYW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A rectangular box has a length of $8$ cm, a width of $5$ cm, and a height of $3$ cm. What is the total surface area of the box, in cm$^2$?', NULL, $lyceon_json$[{"key":"A","text":"$120$"},{"key":"B","text":"$158$"},{"key":"C","text":"$79$"},{"key":"D","text":"$134$"}]$lyceon_json$::jsonb, 'B', NULL, E'The surface area of a rectangular box is $SA = 2(lw + lh + wh)$. Substituting $l = 8$, $w = 5$, $h = 3$: $SA = 2(8 \\times 5 + 8 \\times 3 + 5 \\times 3) = 2(40 + 24 + 15) = 2(79) = 158$ cm$^2$. The answer $120$ comes from computing the volume $8 \\times 5 \\times 3 = 120$ instead of the surface area. The answer $79$ results from computing $lw + lh + wh = 79$ but forgetting to multiply by $2$, accounting for only half the faces. The answer $134$ comes from an arithmetic error such as computing $2(40 + 24 + 3) = 134$, miscomputing $5 \\times 3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM269GE1C', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A store sells a jacket for $\\$80$. During a sale, the price is reduced by $25\\%$. What is the sale price of the jacket?', NULL, $lyceon_json$[{"key":"A","text":"$\\$20$"},{"key":"B","text":"$\\$55$"},{"key":"C","text":"$\\$60$"},{"key":"D","text":"$\\$75$"}]$lyceon_json$::jsonb, 'C', NULL, E'A $25\\%$ discount on $\\$80$ is $0.25 \\times 80 = \\$20$. The sale price is $80 - 20 = \\$60$. The value $\\$20$ is the discount amount itself, not the sale price, resulting from stopping at an intermediate step. The value $\\$55$ comes from an arithmetic slip such as subtracting $\\$25$ instead of $25\\%$ of $\\$80$. The value $\\$75$ results from subtracting only $\\frac{80}{16}$ or applying a $5\\%$ discount instead of $25\\%$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26E5PO8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A study finds that students who eat breakfast daily have higher test scores than students who skip breakfast. The study observed students'' existing habits without assigning them to groups. Which of the following is the best conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Eating breakfast causes higher test scores."},{"key":"B","text":"Skipping breakfast causes lower test scores."},{"key":"C","text":"There is an association between eating breakfast and higher test scores."},{"key":"D","text":"Students who eat breakfast are smarter than students who skip breakfast."}]$lyceon_json$::jsonb, 'C', NULL, E'Because the study is observational — it observed existing habits rather than randomly assigning students to eat or skip breakfast — it can establish an association but cannot establish causation. Confounding variables such as household income or sleep habits could explain the difference. Concluding that eating breakfast causes higher scores overstates what an observational study can show. Similarly, concluding that skipping breakfast causes lower scores implies causation that is not supported. Claiming that breakfast-eating students are inherently smarter goes far beyond the data and introduces an unsupported generalization.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26GPSTQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A researcher surveys a random sample of $400$ adults and finds that $45\\%$ prefer Brand A, with a margin of error of $5\\%$ at $95\\%$ confidence. A second researcher surveys a random sample of $1{,}600$ adults from the same population and also finds that $45\\%$ prefer Brand A. Which of the following best describes the margin of error for the second survey?', NULL, $lyceon_json$[{"key":"A","text":"Approximately $1.25\\%$"},{"key":"B","text":"Approximately $2.5\\%$"},{"key":"C","text":"Approximately $5\\%$"},{"key":"D","text":"Approximately $10\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is inversely proportional to the square root of the sample size. The second sample is $4$ times as large as the first ($1{,}600 = 4 \\times 400$), so the margin of error is reduced by a factor of $\\sqrt{4} = 2$. Therefore, the new margin of error is approximately $\\frac{5\\%}{2} = 2.5\\%$. The value $1.25\\%$ results from dividing by $4$ instead of by $\\sqrt{4}$, treating the margin of error as directly (rather than inversely-square-root) proportional to sample size. The value $5\\%$ assumes the margin of error does not change with sample size, reflecting a fundamental misunderstanding. The value $10\\%$ comes from multiplying the original margin of error by $2$, reversing the relationship between sample size and precision.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM274HRPN', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'What is the value of $x$ in the equation $\\frac{2x - 3}{5} + \\frac{x + 4}{2} = 5$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Multiplying every term by $10$ (the least common denominator of $5$ and $2$) gives $2(2x - 3) + 5(x + 4) = 50$. Expanding: $4x - 6 + 5x + 20 = 50$. Combining like terms: $9x + 14 = 50$. Subtracting $14$ from both sides: $9x = 36$. Dividing by $9$: $x = 4$. A common error is to multiply by $10$ but forget to distribute to both terms in a numerator, leading to an incorrect intermediate equation and a wrong answer.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29D0RVY', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A movie theater sold a total of $200$ tickets for a showing. Adult tickets cost $\\$12$ each and child tickets cost $\\$7$ each. If the theater collected $\\$1{,}800$ in ticket sales, how many adult tickets were sold?', NULL, $lyceon_json$[{"key":"A","text":"$80$"},{"key":"B","text":"$100$"},{"key":"C","text":"$120$"},{"key":"D","text":"$140$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $a$ be the number of adult tickets and $c$ the number of child tickets. The system is $a + c = 200$ and $12a + 7c = 1{,}800$. From the first equation, $c = 200 - a$. Substituting into the second equation: $12a + 7(200 - a) = 1{,}800$, which gives $12a + 1{,}400 - 7a = 1{,}800$, so $5a = 400$ and $a = 80$ (with $c = 120$). Choosing $120$ gives the number of child tickets rather than adult tickets. Choosing $100$ assumes equal numbers of each ticket type without using the revenue equation. Choosing $140$ results from setting up the revenue equation incorrectly, such as swapping the ticket prices for the two types.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AKTO5Y', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Triangle $ABC$ is similar to triangle $DEF$. In triangle $ABC$, $AB = 6$, $BC = 9$, and $AC = 12$. If $DE = 10$, what is the length of $EF$?', NULL, $lyceon_json$[{"key":"A","text":"$13$"},{"key":"B","text":"$15$"},{"key":"C","text":"$18$"},{"key":"D","text":"$20$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since triangle $ABC$ is similar to triangle $DEF$, corresponding sides are proportional. The ratio of similarity is $\\frac{DE}{AB} = \\frac{10}{6} = \\frac{5}{3}$. Therefore $EF = BC \\times \\frac{5}{3} = 9 \\times \\frac{5}{3} = 15$. The answer $13$ comes from adding $4$ (the difference $10 - 6$) to $9$ instead of multiplying by the scale factor. The answer $18$ results from doubling $BC$ rather than applying the correct ratio. The answer $20$ comes from applying the scale factor to $AC = 12$ instead of $BC = 9$, finding $DF$ rather than $EF$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AU7K0P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A standard deck of $52$ playing cards contains $4$ aces. If one card is drawn at random, what is the probability that the card is an ace?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{52}$"},{"key":"B","text":"$\\frac{1}{13}$"},{"key":"C","text":"$\\frac{1}{4}$"},{"key":"D","text":"$\\frac{4}{13}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The probability of drawing an ace is $\\frac{4}{52} = \\frac{1}{13}$. The value $\\frac{1}{52}$ results from treating only one ace as favorable rather than all four. The value $\\frac{1}{4}$ comes from dividing by the number of suits rather than the total number of cards. The value $\\frac{4}{13}$ results from dividing $4$ by $13$ (the number of ranks) instead of by $52$ (the total number of cards).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AZCRNJ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A plumber charges a $\\$60$ service fee plus $\\$45$ per hour of labor. If $C(t)$ represents the total charge in dollars for $t$ hours of labor, what is the rate of change of $C$ and how many hours of labor result in a total charge of $\\$285$?', NULL, $lyceon_json$[{"key":"A","text":"Rate of change: $45$; hours: $5$"},{"key":"B","text":"Rate of change: $60$; hours: $5$"},{"key":"C","text":"Rate of change: $45$; hours: $3$"},{"key":"D","text":"Rate of change: $105$; hours: $4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function is $C(t) = 45t + 60$. The rate of change is the coefficient of $t$, which is $45$ dollars per hour. Setting $C(t) = 285$: $45t + 60 = 285$, so $45t = 225$ and $t = 5$. The choice with rate of change $60$ confuses the fixed service fee with the per-hour rate, a fundamental misunderstanding of slope versus intercept. The choice with $3$ hours correctly identifies the rate but arrives at $t = 3$ by dividing $285$ by the combined amount $45 + 60 = 105$ and rounding, stopping before properly isolating $t$. The choice with rate of change $105$ adds the fee and rate together ($45 + 60 = 105$) as if both scale with hours, setting up the model incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BBGH7S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A factory produces $480$ widgets in $6$ hours using $4$ machines. If $2$ additional machines of the same type are brought in and all $6$ machines work at the same constant rate, how many widgets will the factory produce in $8$ hours?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '960', ARRAY['960'], E'Each machine produces $\\frac{480}{4 \\times 6} = 20$ widgets per hour. With $6$ machines running for $8$ hours, the total production is $6 \\times 20 \\times 8 = 960$ widgets. A common error is forgetting to account for the additional machines and computing $480 \\times \\frac{8}{6} = 640$. Another error is computing the rate per machine incorrectly by dividing $480$ only by $6$ hours and not by the $4$ machines, giving $80$ widgets per hour per machine, which leads to an inflated answer.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BCTKR5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'The equation $x^2 + y^2 - 6x + 10y + 18 = 0$ represents a circle in the $xy$-plane. What is the radius of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$\\sqrt{7}$"},{"key":"C","text":"$16$"},{"key":"D","text":"$\\sqrt{34}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewrite the equation by completing the square. Group the $x$- and $y$-terms: $(x^2 - 6x) + (y^2 + 10y) = -18$. Complete the square for $x$: $x^2 - 6x + 9 = (x - 3)^2$. Complete the square for $y$: $y^2 + 10y + 25 = (y + 5)^2$. Adding $9$ and $25$ to both sides gives $(x - 3)^2 + (y + 5)^2 = -18 + 9 + 25 = 16$. Since $r^2 = 16$, the radius is $r = 4$. The answer $\\sqrt{7}$ results from a sign error when moving $18$ to the right side, computing $-18 + 25 = 7$ and forgetting to add $9$. The answer $16$ confuses $r^2$ with $r$, reporting the squared radius. The answer $\\sqrt{34}$ comes from adding $9 + 25 = 34$ without subtracting $18$, omitting the constant term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BP25CN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A jar contains $8$ red, $12$ yellow, and $10$ white jelly beans. Two jelly beans are selected at random without replacement. What is the probability that both jelly beans are yellow?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2}{15}$"},{"key":"B","text":"$\\frac{22}{145}$"},{"key":"C","text":"$\\frac{4}{29}$"},{"key":"D","text":"$\\frac{36}{225}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of jelly beans is $8 + 12 + 10 = 30$. The probability that the first jelly bean is yellow is $\\frac{12}{30}$. Without replacement, the probability that the second is also yellow is $\\frac{11}{29}$. Multiplying gives $\\frac{12}{30} \\times \\frac{11}{29} = \\frac{132}{870} = \\frac{22}{145}$. The value $\\frac{2}{15}$ comes from computing $\\frac{12}{30} \\times \\frac{10}{30} = \\frac{120}{900} = \\frac{2}{15}$, subtracting $2$ from the numerator instead of $1$ after the first draw (using $10$ remaining yellow instead of $11$) while also keeping the denominator at $30$ instead of reducing it to $29$. The value $\\frac{4}{29}$ results from an arithmetic error when simplifying the product. The value $\\frac{36}{225}$ equals $\\frac{4}{25}$, which comes from computing $\\left(\\frac{12}{30}\\right)^2 = \\frac{144}{900}$ as though the draws were independent, treating the selection as with replacement.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CM7ANI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'grid_in', E'A scientist models the relationship between the dosage of a medication ($x$, in milligrams) and the reduction in symptoms ($y$, measured on a $100$-point scale) using the equation $y = -0.5x^2 + 12x$. According to this model, what is the maximum reduction in symptoms?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '72', ARRAY['72'], E'The equation $y = -0.5x^2 + 12x$ is a downward-opening parabola. The maximum occurs at the vertex, where $x = \\frac{-b}{2a} = \\frac{-12}{2(-0.5)} = \\frac{-12}{-1} = 12$. Substituting $x = 12$: $y = -0.5(144) + 12(12) = -72 + 144 = 72$. A common error is reporting the $x$-value of the vertex ($12$) instead of the $y$-value, which answers a different question (the optimal dosage rather than the maximum symptom reduction). Another error is using $\\frac{-b}{a}$ instead of $\\frac{-b}{2a}$, giving $x = 24$, and then computing $y = -0.5(576) + 12(24) = -288 + 288 = 0$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D3CCRE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A company tested $400$ products for defects. The results are summarized in the table below.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DBNWE4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'The population of a town was $12{,}000$ in $2020$. By $2023$, the population had increased to $13{,}440$. What was the percent increase in the town''s population from $2020$ to $2023$?', NULL, $lyceon_json$[{"key":"A","text":"$4\\%$"},{"key":"B","text":"$10.7\\%$"},{"key":"C","text":"$12\\%$"},{"key":"D","text":"$14.4\\%$"}]$lyceon_json$::jsonb, 'C', NULL, E'The increase is $13{,}440 - 12{,}000 = 1{,}440$. The percent increase is $\\frac{1{,}440}{12{,}000} \\times 100 = 12\\%$. The value $4\\%$ results from dividing the increase by $3$ years to get $480$ per year and then computing $\\frac{480}{12{,}000} \\times 100$, which gives the annual rate but does not answer the question about total percent increase. The value $10.7\\%$ comes from dividing the change by the final population ($\\frac{1{,}440}{13{,}440}$) instead of the original population. The value $14.4\\%$ results from an arithmetic error such as computing $\\frac{1{,}440}{10{,}000} \\times 100$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DD0ROY', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A taxi service charges a base fare of $\\$3.50$ plus $\\$2.25$ per mile. A passenger has at most $\\$30$ to spend on the ride. Which inequality can be used to find $m$, the maximum number of miles the passenger can travel?', NULL, $lyceon_json$[{"key":"A","text":"$2.25m + 3.50 \\leq 30$"},{"key":"B","text":"$2.25m + 3.50 \\geq 30$"},{"key":"C","text":"$3.50m + 2.25 \\leq 30$"},{"key":"D","text":"$2.25m - 3.50 \\leq 30$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the base fare $\\$3.50$ plus $\\$2.25$ per mile, giving $2.25m + 3.50$. Since the passenger can spend at most $\\$30$, the total must be less than or equal to $30$, so the inequality is $2.25m + 3.50 \\leq 30$. Using $\\geq$ instead of $\\leq$ reverses the constraint, finding costs that exceed the budget rather than stay within it. Swapping the coefficients so that $3.50$ multiplies $m$ confuses the per-mile rate with the base fare. Subtracting $3.50$ instead of adding it misrepresents how the base fare contributes to the total cost.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DGEVJF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The ages of $7$ members of a club are $18$, $19$, $20$, $21$, $22$, $23$, and $45$. If the outlier $45$ is removed from the data set, which of the following best describes the effect on the mean and median?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and the median will decrease."},{"key":"B","text":"The mean will decrease, but the median will remain the same."},{"key":"C","text":"The median will decrease, but the mean will remain the same."},{"key":"D","text":"Both the mean and the median will remain the same."}]$lyceon_json$::jsonb, 'A', NULL, E'With all $7$ values, the mean is $\\frac{18 + 19 + 20 + 21 + 22 + 23 + 45}{7} = \\frac{168}{7} = 24$ and the median is the $4$th value, $21$. After removing $45$, the mean becomes $\\frac{123}{6} = 20.5$ and the median becomes the average of the $3$rd and $4$th values: $\\frac{20 + 21}{2} = 20.5$. Both decrease. The claim that the median stays the same overlooks that removing a value changes the position of the middle, shifting the median from $21$ to $20.5$. The claim that the mean stays the same ignores that removing a large value pulls the mean down. The claim that neither changes is incorrect for both reasons.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EJQ5S7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A scatterplot shows the relationship between the age of a used car (in years) and its resale value (in thousands of dollars). The line of best fit has equation $y = -1.8x + 25$, where $x$ is the age and $y$ is the resale value. According to this model, by how many thousands of dollars does the resale value decrease for each additional year of the car''s age?', NULL, $lyceon_json$[{"key":"A","text":"$1.8$"},{"key":"B","text":"$23.2$"},{"key":"C","text":"$25$"},{"key":"D","text":"$0.18$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope of $-1.8$ indicates that for each additional year of age, the resale value decreases by $1.8$ thousand dollars. The question asks by how many thousands of dollars the value decreases, so the answer is $1.8$. The value $23.2$ is the predicted resale value at $x = 1$ ($-1.8(1) + 25 = 23.2$), which is a single predicted value rather than the rate of change. The value $25$ is the $y$-intercept, representing the predicted value of a brand-new car, not the rate of depreciation per year. The value $0.18$ results from a unit error, such as dividing the slope by $10$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GGJXN6', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the sum of the solutions to the equation $x^2 - 7x + 10 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$10$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring gives $(x - 2)(x - 5) = 0$, so $x = 2$ or $x = 5$. The sum of the solutions is $2 + 5 = 7$. By Vieta''s formulas, the sum of the roots of $x^2 - 7x + 10 = 0$ equals $7$. The value $-7$ comes from taking the coefficient of $x$ without correcting the sign. The value $10$ is the product of the roots, not their sum. The value $3$ is the difference $5 - 2$, not the sum.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GIJB9Q', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two straight lines intersect at a point. One of the angles formed measures $48°$. What is the measure of the angle that is vertical to it?', NULL, $lyceon_json$[{"key":"A","text":"$42°$"},{"key":"B","text":"$48°$"},{"key":"C","text":"$132°$"},{"key":"D","text":"$96°$"}]$lyceon_json$::jsonb, 'B', NULL, E'Vertical angles are the pair of non-adjacent angles formed when two lines intersect, and they are always equal. Therefore the vertical angle also measures $48°$. The answer $42°$ results from subtracting from $90°$, confusing vertical angles with complementary angles. The answer $132°$ comes from computing the supplement $180° - 48°$, which gives an adjacent angle, not the vertical angle. The answer $96°$ comes from incorrectly doubling $48°$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
