INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H9VR1S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set of $20$ values has a mean of $50$ and a standard deviation of $8$. Each value in the data set is multiplied by $3$ and then $10$ is added to the result. What are the new mean and new standard deviation of the transformed data set?', NULL, $lyceon_json$[{"key":"A","text":"Mean: $160$, Standard deviation: $24$"},{"key":"B","text":"Mean: $160$, Standard deviation: $34$"},{"key":"C","text":"Mean: $150$, Standard deviation: $24$"},{"key":"D","text":"Mean: $150$, Standard deviation: $8$"}]$lyceon_json$::jsonb, 'A', NULL, E'When each value $x$ is transformed to $3x + 10$, the mean transforms the same way: $3(50) + 10 = 160$. The standard deviation is affected only by the multiplicative factor, not the additive constant, so the new standard deviation is $3 \\times 8 = 24$. The answer with standard deviation $34$ incorrectly adds $10$ to the standard deviation as well, treating the additive shift as affecting spread. The answer with mean $150$ computes $3 \\times 50 = 150$ but forgets to add $10$. The answer with standard deviation $8$ assumes the transformation does not change the standard deviation at all, ignoring the multiplicative scaling.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HXAA0I', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The graph of $f(x) = a(x - 3)^2 + 7$ opens downward and has a vertex at $(3, 7)$. Which of the following could be the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$0$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'C', NULL, E'For the parabola to open downward, the leading coefficient $a$ must be negative. Among the choices, $-3$ is the only negative value. The value $2$ is positive, which would make the parabola open upward, contradicting the given condition. The value $0$ would eliminate the squared term entirely, producing a horizontal line rather than a parabola. The value $7$ is the $y$-coordinate of the vertex, not the leading coefficient, and being positive would also cause the parabola to open upward.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JS3Z1U', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $3(2x + 5) = 7x - 4$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$-19$"},{"key":"B","text":"$-1$"},{"key":"C","text":"$11$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'D', NULL, E'Distributing on the left side gives $6x + 15 = 7x - 4$. Subtracting $6x$ from both sides yields $15 = x - 4$. Adding $4$ to both sides gives $x = 19$. The value $-19$ results from a sign error when rearranging, producing $-x = 19$ and concluding $x = -19$. The value $-1$ comes from an arithmetic slip such as incorrectly computing $6x + 15 = 7x - 4$ as $6x - 7x = -4 - 15$ yielding $-x = -19$ but then dividing by $-1$ incorrectly. The value $11$ results from computing $15 - 4 = 11$ instead of $15 + 4 = 19$, treating $15 = x - 4$ as though it were $x = 15 - 4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KWM4NE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A poll of $500$ randomly selected residents found that $62\\%$ favor a new recycling program, with a margin of error of $4\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between $58\\%$ and $66\\%$ of the sampled residents favor the program."},{"key":"B","text":"It is plausible that between $58\\%$ and $66\\%$ of all residents favor the program."},{"key":"C","text":"Exactly $62\\%$ of all residents favor the program."},{"key":"D","text":"Between $58\\%$ and $66\\%$ of all residents will always favor the program."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error creates a confidence interval of $62\\% \\pm 4\\%$, or $58\\%$ to $66\\%$, for the population parameter. This means it is plausible that between $58\\%$ and $66\\%$ of all residents favor the program. The interpretation that this range applies only to the sampled residents is incorrect because the margin of error is specifically about estimating the population, not describing the sample. Stating that exactly $62\\%$ of all residents favor the program ignores the uncertainty captured by the margin of error. Claiming the range will always hold ignores that the interval is an estimate with a stated confidence level, not a permanent guarantee.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KXW9EO', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $5x - 8 = 17$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$9$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding $8$ to both sides gives $5x = 25$, and dividing both sides by $5$ gives $x = 5$. The value $3$ results from subtracting $8$ from $17$ to get $9$ and then dividing by an incorrect factor, stopping partway through the correct process. The value $9$ comes from computing $17 - 8 = 9$ and reporting that as the answer without dividing by $5$, setting up the isolation step incorrectly. The value $25$ results from computing $17 + 8 = 25$ and reporting that without dividing by $5$, misreading the subtraction as addition.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M1NAG3', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many real solutions does the equation $2x^2 + 4x + 5 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = 4^2 - 4(2)(5) = 16 - 40 = -24$. Since the discriminant is negative, the equation has no real solutions. Choosing $1$ reflects the misconception that a negative discriminant guarantees exactly one repeated root, confusing it with a discriminant of zero. Choosing $2$ ignores the discriminant entirely and assumes all quadratics have two real solutions. Choosing $4$ likely comes from misreading the coefficient of $x$ as the number of solutions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M4130D', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A student recorded the following quiz scores: $82$, $91$, $75$, $91$, $68$. What is the mode of the quiz scores?', NULL, $lyceon_json$[{"key":"A","text":"$68$"},{"key":"B","text":"$82$"},{"key":"C","text":"$91$"},{"key":"D","text":"$81.4$"}]$lyceon_json$::jsonb, 'C', NULL, E'The mode is the value that appears most frequently. In the data set $68, 75, 82, 91, 91$, the value $91$ appears twice while all other values appear once, so the mode is $91$. The value $68$ is the minimum, not the mode, reflecting a confusion between the two measures. The value $82$ is the median of the sorted data, not the mode. The value $81.4$ is the mean ($\\frac{68 + 75 + 82 + 91 + 91}{5} = \\frac{407}{5} = 81.4$), which is a different measure of center.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NFJIV0', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $f$ satisfies $f(2) = 9$ and $f(8) = -3$. What is the value of $f(f(5))$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$3$"},{"key":"C","text":"$7$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'C', NULL, E'The slope of $f$ is $\\frac{-3 - 9}{8 - 2} = \\frac{-12}{6} = -2$. Using point-slope form with $(2, 9)$: $f(x) = -2(x - 2) + 9 = -2x + 13$. First, $f(5) = -2(5) + 13 = 3$. Then $f(f(5)) = f(3) = -2(3) + 13 = 7$. The value $-3$ comes from confusing $f(f(5))$ with $f(8)$, substituting $8$ instead of the computed inner value. The value $3$ results from computing $f(5) = 3$ but stopping without applying $f$ a second time. The value $13$ is the $y$-intercept of $f$, which a student might report if they misread the question as asking for $f(0)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NNRA44', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'Researchers want to determine whether a new fertilizer increases tomato plant growth. They randomly assign $60$ tomato plants to two groups: $30$ receive the new fertilizer and $30$ receive the standard fertilizer. After $8$ weeks, the plants receiving the new fertilizer have a significantly greater average height. Which of the following conclusions is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The new fertilizer is likely the cause of the greater average height."},{"key":"B","text":"There is an association between the type of fertilizer and plant height, but causation cannot be determined."},{"key":"C","text":"The results apply to all types of plants, not just tomato plants."},{"key":"D","text":"The results would be the same if the experiment lasted $16$ weeks."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the study is a randomized controlled experiment — plants were randomly assigned to treatment and control groups — a causal conclusion is appropriate when a significant difference is observed. The claim that only an association can be established applies to observational studies, not to well-designed experiments with random assignment. Generalizing the results to all plant types goes beyond the scope of the study, which tested only tomato plants. Predicting identical results over a longer time period is speculation not supported by the $8$-week data.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NUPB24', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A laptop originally priced at $\\$1{,}200$ is discounted by $15\\%$. A customer has a coupon for an additional $10\\%$ off the discounted price. What is the final price, in dollars, that the customer pays?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '918', ARRAY['918'], E'The first discount reduces the price by $15\\%$: $1{,}200 \\times 0.85 = 1{,}020$. The coupon then reduces this price by $10\\%$: $1{,}020 \\times 0.90 = 918$. A common error is adding the two percentages to get a $25\\%$ total discount and computing $1{,}200 \\times 0.75 = 900$, which incorrectly treats successive percent reductions as additive. Another error is applying both discounts to the original price separately and subtracting both: $1{,}200 - 180 - 120 = 900$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OV5WYA', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $2(x^2 - 3) + 4x^2$?', NULL, $lyceon_json$[{"key":"A","text":"$6x^2 - 3$"},{"key":"B","text":"$6x^2 - 6$"},{"key":"C","text":"$2x^2 - 6$"},{"key":"D","text":"$6x^2 + 6$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing the $2$ gives $2x^2 - 6 + 4x^2$. Combining like terms yields $6x^2 - 6$. The expression $6x^2 - 3$ results from failing to distribute the $2$ to the constant $-3$. The expression $2x^2 - 6$ comes from forgetting to add the $4x^2$ term. The expression $6x^2 + 6$ results from a sign error, treating $-3$ as $+3$ during distribution.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P7VNQ4', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{6x^3 - 12x^2}{3x}$ for all $x \\neq 0$?', NULL, $lyceon_json$[{"key":"A","text":"$2x^2 - 4x$"},{"key":"B","text":"$2x^3 - 4x^2$"},{"key":"C","text":"$2x^2 - 12x$"},{"key":"D","text":"$2x - 4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Dividing each term by $3x$ gives $\\frac{6x^3}{3x} - \\frac{12x^2}{3x} = 2x^2 - 4x$. The expression $2x^3 - 4x^2$ results from dividing only the coefficients by $3$ without reducing the exponents. The expression $2x^2 - 12x$ comes from dividing only the first term''s coefficient correctly while dividing the second term only by $x$. The expression $2x - 4$ results from subtracting $2$ from each exponent instead of $1$, over-reducing the powers.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PPCAOH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A car travels $150$ miles using $5$ gallons of gasoline. A truck travels $180$ miles using $9$ gallons of gasoline. How many more miles per gallon does the car get than the truck?', NULL, $lyceon_json$[{"key":"A","text":"$10$"},{"key":"B","text":"$15$"},{"key":"C","text":"$20$"},{"key":"D","text":"$30$"}]$lyceon_json$::jsonb, 'A', NULL, E'The car''s fuel efficiency is $\\frac{150}{5} = 30$ miles per gallon. The truck''s fuel efficiency is $\\frac{180}{9} = 20$ miles per gallon. The difference is $30 - 20 = 10$ miles per gallon. The value $15$ results from computing the average of the two rates rather than their difference. The value $20$ is the truck''s rate alone, which would result from misreading the question as asking for the truck''s fuel efficiency. The value $30$ is the car''s rate alone, obtained by ignoring the comparison entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QOI3V0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $100$ voters in a city found that $58$ support a new park proposal. Based on this sample, what is the best estimate of the proportion of all voters in the city who support the proposal?', NULL, $lyceon_json$[{"key":"A","text":"$0.42$"},{"key":"B","text":"$0.50$"},{"key":"C","text":"$0.58$"},{"key":"D","text":"$1.00$"}]$lyceon_json$::jsonb, 'C', NULL, E'The best estimate of the population proportion is the sample proportion itself: $\\frac{58}{100} = 0.58$. The value $0.42$ is the proportion who do not support the proposal, answering the opposite of what was asked. The value $0.50$ assumes the population is evenly split, ignoring the sample data entirely. The value $1.00$ incorrectly treats the number of supporters as the proportion rather than dividing by the sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
