INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SH261A', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a $45°$-$45°$-$90°$ triangle, each leg has length $5$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$5\\sqrt{2}$"},{"key":"C","text":"$5\\sqrt{3}$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'In a $45°$-$45°$-$90°$ triangle, the hypotenuse is $\\sqrt{2}$ times the length of a leg. With each leg equal to $5$, the hypotenuse is $5\\sqrt{2}$. The answer $5$ incorrectly assumes the hypotenuse equals a leg, ignoring the $\\sqrt{2}$ factor. The answer $5\\sqrt{3}$ confuses the $45°$-$45°$-$90°$ ratio with the $30°$-$60°$-$90°$ ratio, where the longer leg is $\\sqrt{3}$ times the shorter leg. The answer $10$ results from doubling the leg length instead of multiplying by $\\sqrt{2}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T36MD2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A sphere has a surface area of $144\\pi$ square centimeters. What is the volume of the sphere, in cubic centimeters? (Express your answer as a value in the form $k\\pi$ and enter the value of $k$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '288', ARRAY['288'], E'The surface area of a sphere is $SA = 4\\pi r^2$. Setting $4\\pi r^2 = 144\\pi$ and dividing both sides by $4\\pi$ gives $r^2 = 36$, so $r = 6$ cm. The volume of a sphere is $V = \\frac{4}{3}\\pi r^3 = \\frac{4}{3}\\pi(6)^3 = \\frac{4}{3}\\pi(216) = 288\\pi$ cubic centimeters. Therefore the coefficient of $\\pi$ is $288$. A common error is taking $r = 12$ by forgetting to divide by $4$ when solving $4\\pi r^2 = 144\\pi$, which gives $r^2 = 144$ instead of $r^2 = 36$. Another error is omitting the $\\frac{4}{3}$ factor, computing $\\pi r^3 = 216\\pi$ instead.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T7SCYM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for $3$ cups of flour to make $24$ cookies. At this rate, how many cups of flour are needed to make $40$ cookies?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$6$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{3 \\text{ cups}}{24 \\text{ cookies}} = \\frac{1}{8}$ cup per cookie. For $40$ cookies: $40 \\times \\frac{1}{8} = 5$ cups. The value $4$ comes from computing $\\frac{40 - 24}{24} \\times 3 + 3$ incorrectly or stopping at an intermediate step. The value $6$ results from an arithmetic slip such as computing $40 \\times \\frac{3}{20}$ instead of $40 \\times \\frac{3}{24}$. The value $8$ comes from setting up the proportion incorrectly, such as using $\\frac{24}{3} = \\frac{40}{x}$ and solving $x = \\frac{40 \\times 3}{24}$ as $\\frac{120}{15}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TOXU3T', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In an isosceles triangle, the two equal angles each measure $(3x + 5)°$ and the third angle measures $(2x + 10)°$. What is the measure, in degrees, of each of the two equal angles?', NULL, $lyceon_json$[{"key":"A","text":"$20°$"},{"key":"B","text":"$50°$"},{"key":"C","text":"$65°$"},{"key":"D","text":"$70°$"}]$lyceon_json$::jsonb, 'C', NULL, E'The sum of angles in a triangle is $180°$. Setting up the equation: $2(3x + 5) + (2x + 10) = 180$. Expanding gives $6x + 10 + 2x + 10 = 180$, so $8x + 20 = 180$, which yields $8x = 160$ and $x = 20$. Substituting back into the expression for the equal angles: $3(20) + 5 = 65°$. The answer $20°$ is the value of $x$ itself, not the angle measure. The answer $50°$ comes from computing the third angle $2(20) + 10 = 50°$ instead of the requested equal angles. The answer $70°$ results from substituting $x = 20$ into the wrong expression, computing $3(20) + 10 = 70°$ by mixing up the two angle formulas.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X5CZY0', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'Line $m$ has the equation $2x - 5y = 20$. Line $n$ is parallel to line $m$ and passes through the point $(10, 3)$. What is the $x$-intercept of line $n$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5/2', ARRAY['5/2', '2.5'], E'Rewriting $2x - 5y = 20$ in slope-intercept form gives $y = \\frac{2}{5}x - 4$, so line $m$ has slope $\\frac{2}{5}$. Since line $n$ is parallel, it also has slope $\\frac{2}{5}$. Using point-slope form with $(10, 3)$: $y - 3 = \\frac{2}{5}(x - 10)$, which simplifies to $y = \\frac{2}{5}x - 4 + 3 = \\frac{2}{5}x - 1$. To find the $x$-intercept, set $y = 0$: $0 = \\frac{2}{5}x - 1$, so $\\frac{2}{5}x = 1$ and $x = \\frac{5}{2}$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X8WSNW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $g$ is defined by $g(x) = 2^{x+1} - 8$. What is the $x$-intercept of the graph of $y = g(x)$ in the $xy$-plane?', NULL, $lyceon_json$[{"key":"A","text":"$(2, 0)$"},{"key":"B","text":"$(3, 0)$"},{"key":"C","text":"$(4, 0)$"},{"key":"D","text":"$(1, 0)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $g(x) = 0$ gives $2^{x+1} = 8$. Since $8 = 2^3$, we have $x + 1 = 3$, which gives $x = 2$. The $x$-intercept is $(2, 0)$. The point $(3, 0)$ results from solving $2^x = 8$ without accounting for the $+1$ in the exponent. The point $(4, 0)$ reflects confusing $2^{x+1} = 8$ with a linear equation or computing $2^4 = 16$ and misidentifying it as $8$. The point $(1, 0)$ comes from an error in subtracting, such as computing $3 - 1 = 2$ but then reporting $x = 1$ instead.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XBKBSO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $7$ cm. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$14\\pi$ cm$^2$"},{"key":"B","text":"$49\\pi$ cm$^2$"},{"key":"C","text":"$7\\pi$ cm$^2$"},{"key":"D","text":"$49$ cm$^2$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a circle is $A = \\pi r^2$. Substituting $r = 7$ gives $A = \\pi(7)^2 = 49\\pi$ cm$^2$. The answer $14\\pi$ comes from using the circumference formula $2\\pi r$ instead of the area formula. The answer $7\\pi$ results from computing $\\pi r$ instead of $\\pi r^2$, omitting the squaring step. The answer $49$ computes $r^2$ correctly but omits the factor of $\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YKDPQE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A school principal wants to test whether a new teaching method improves math scores. She allows students to choose whether to enroll in a class using the new method or a class using the traditional method. At the end of the semester, students in the new-method class score an average of $12$ points higher. A teacher claims the new method caused the improvement. Which of the following best explains why the teacher''s claim may not be valid?', NULL, $lyceon_json$[{"key":"A","text":"The sample size was too small to detect a difference of $12$ points."},{"key":"B","text":"Students who chose the new method may differ systematically from those who chose the traditional method, creating a confounding variable."},{"key":"C","text":"The $12$-point difference is not statistically significant."},{"key":"D","text":"The teacher's claim is valid because the sample size of students was large enough to establish causation."}]$lyceon_json$::jsonb, 'B', NULL, E'The key flaw in the study design is self-selection: because students chose their own group, those who opted for the new method may already be more motivated, higher-achieving, or otherwise systematically different from those who chose the traditional method. This creates a confounding variable that makes it impossible to attribute the $12$-point difference to the teaching method alone. The objection about sample size is not supported by the information given, since no sample size is specified as insufficient. The claim that the difference is not statistically significant is unsupported — the problem states the difference exists but asks about the validity of the causal interpretation, not whether the difference is real. The claim that the teacher is valid because of sample size confuses sample size with study design; a large sample in an observational study still cannot establish causation without random assignment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YLSHEZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A triangle has a base of $10$ inches and a height of $6$ inches. What is the area of the triangle, in square inches?', NULL, $lyceon_json$[{"key":"A","text":"$16$"},{"key":"B","text":"$30$"},{"key":"C","text":"$60$"},{"key":"D","text":"$32$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a triangle is $A = \\frac{1}{2} \\times \\text{base} \\times \\text{height} = \\frac{1}{2}(10)(6) = 30$ square inches. The answer $60$ results from computing base times height without the $\\frac{1}{2}$ factor, using the rectangle area formula instead. The answer $16$ comes from adding the base and height ($10 + 6 = 16$) instead of using the area formula. The answer $32$ results from a calculation error such as computing $\\frac{1}{2}(10)(6)$ as $\\frac{1}{2}(64)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YR6YPZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'$$\\frac{5}{x - 3} - \\frac{2}{x + 3} = \\frac{24}{x^2 - 9}$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z02MAE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'The equation $y = 2.5x + 15$ models the relationship between the number of items purchased ($x$) and the total cost in dollars ($y$) at an online store. What does the $y$-intercept of this equation represent in context?', NULL, $lyceon_json$[{"key":"A","text":"The cost per item purchased"},{"key":"B","text":"The shipping fee when no items are purchased"},{"key":"C","text":"The total cost when $2.5$ items are purchased"},{"key":"D","text":"The number of items that can be purchased for $\\$15$"}]$lyceon_json$::jsonb, 'B', NULL, E'The $y$-intercept is the value of $y$ when $x = 0$. In this model, when $0$ items are purchased, the total cost is $\\$15$, which represents a fixed charge such as a shipping fee. The cost per item is represented by the slope $2.5$, not the $y$-intercept. The claim about $2.5$ items conflates the slope value with a quantity of items. The claim about the number of items for $\\$15$ reverses the roles of the variables, treating $y = 15$ as the input rather than the output at $x = 0$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z4HFQ1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A central angle of $\\frac{\\pi}{3}$ radians is formed in a circle of radius $9$. What is the length of the arc intercepted by this angle?', NULL, $lyceon_json$[{"key":"A","text":"$3\\pi$"},{"key":"B","text":"$6\\pi$"},{"key":"C","text":"$27\\pi$"},{"key":"D","text":"$\\frac{\\pi}{27}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The arc length formula is $s = r\\theta$, where $r$ is the radius and $\\theta$ is the central angle in radians. Substituting $r = 9$ and $\\theta = \\frac{\\pi}{3}$ gives $s = 9 \\cdot \\frac{\\pi}{3} = 3\\pi$. The answer $6\\pi$ results from using the diameter instead of the radius, computing $2(9) \\cdot \\frac{\\pi}{3}$. The answer $27\\pi$ comes from computing $\\pi r^2 \\cdot \\frac{1}{3}$, confusing arc length with sector area. The answer $\\frac{\\pi}{27}$ results from dividing $\\frac{\\pi}{3}$ by $9$ instead of multiplying.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW202LH4M', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Political scientist Adaeze Obi examined voter turnout patterns in municipal elections across thirty mid-sized American cities between 2014 and 2022. She found that cities which moved their municipal elections to coincide with state or national election dates saw average turnout rise from 21 percent to 48 percent. Cities that kept their elections on separate, off-cycle dates saw no significant change in turnout. Obi also noted that in cities with concurrent elections, the demographic composition of the municipal electorate more closely resembled that of the city''s overall adult population, whereas off-cycle electorates skewed older, wealthier, and whiter. Obi concludes that holding municipal elections on separate dates effectively ________', $lyceon_json$[{"key":"A","text":"produces an electorate that is unrepresentative of the broader population the elected officials will serve."},{"key":"B","text":"ensures that voters give more careful consideration to local candidates and ballot measures."},{"key":"C","text":"increases the influence of younger and lower-income voters on municipal policy outcomes."},{"key":"D","text":"has no measurable effect on the quality of governance in mid-sized American cities."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that off-cycle municipal electorates skew older, wealthier, and whiter compared with the overall population, so the logical conclusion is that separate election dates produce an electorate unrepresentative of the broader community. The choice about voters giving more careful consideration to local candidates introduces a claim the passage does not address; Obi''s research concerns turnout and demographics, not the quality of voter deliberation. The choice about increasing the influence of younger and lower-income voters reverses the finding, since concurrent elections — not off-cycle elections — brought the electorate closer to the overall population''s demographics. The choice about no measurable effect on governance quality addresses an outcome the passage does not examine; Obi studied turnout and demographic composition, not governance quality.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20I9NDP', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does "wanting" most nearly mean?', E'Although the experiment''s design was innovative, the researcher''s analysis was found wanting by the peer reviewers, who noted several statistical errors and an incomplete discussion of alternative explanations for the observed results.', $lyceon_json$[{"key":"A","text":"lacking"},{"key":"B","text":"desiring"},{"key":"C","text":"requesting"},{"key":"D","text":"pursuing"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "lacking." The expression "found wanting" is an idiom meaning found to be deficient or inadequate, and the passage reinforces this with specific criticisms: statistical errors and an incomplete discussion. "Desiring" means wishing for something, but the analysis itself cannot wish or desire; substituting it produces the incoherent phrase "analysis was found desiring by the peer reviewers." "Requesting" means asking for something, which is similarly incoherent when applied to an analysis being evaluated for quality. "Pursuing" means chasing or following, which cannot describe the state of a written analysis under critical review.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21CRKUJ', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference between Tanaka''s claim in Text 1 and Obi''s claim in Text 2?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27JUEV4', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A music historian argues that the development of jazz in New Orleans was shaped as much by the city''s unique legal and social structures as by its musicians'' artistic innovations. Which quotation from the text would most directly support this argument?', E'Jazz historian Claudette Beaumont''s 2024 study, Syncopated City, traces the emergence of jazz in early twentieth-century New Orleans. Beaumont notes that the city''s Code Noir, a set of colonial-era laws governing the lives of enslaved and free Black people, had the unintended effect of preserving African musical traditions by permitting gatherings in Congo Square where drumming and call-and-response singing persisted for decades. She also observes that New Orleans'' distinctive ward-based political system created neighborhood social clubs that hired brass bands for parades and funerals, providing steady employment that allowed musicians to professionalize. Beaumont writes: "The very ordinances that regulated public assembly paradoxically sustained the communal musical spaces without which jazz''s improvisatory ethos could not have taken root." She adds that "the musicians'' genius lay in synthesis, but the institutional scaffolding that made synthesis possible was a product of the city''s peculiar governance."', $lyceon_json$[{"key":"A","text":"\"The very ordinances that regulated public assembly paradoxically sustained the communal musical spaces without which jazz's improvisatory ethos could not have taken root.\""},{"key":"B","text":"\"the musicians' genius lay in synthesis, but the institutional scaffolding that made synthesis possible was a product of the city's peculiar governance.\""},{"key":"C","text":"Beaumont notes that the Code Noir permitted gatherings in Congo Square where drumming and call-and-response singing persisted for decades."},{"key":"D","text":"New Orleans' ward-based political system created neighborhood social clubs that hired brass bands for parades and funerals."}]$lyceon_json$::jsonb, 'B', NULL, E'The quotation about institutional scaffolding being a product of the city''s governance most directly supports the argument because it explicitly frames the city''s legal and social structures as the enabling conditions for jazz, while acknowledging musical innovation as secondary. The quotation about ordinances sustaining communal musical spaces supports the argument partially by showing how laws preserved musical gatherings, but it addresses only one mechanism (public assembly regulation) rather than the broader claim about legal and social structures shaping jazz overall. The detail about the Code Noir permitting Congo Square gatherings illustrates one specific legal effect but is a paraphrased observation rather than Beaumont''s direct argument about structural causation. The detail about ward-based social clubs describes a social structure that supported musicians but does not explicitly connect institutional structures to the development of jazz as an art form.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW297IYF7', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'The coelacanth, a deep-sea fish once believed to have gone extinct with the dinosaurs, was rediscovered in 1938 off the coast of South Africa. Genetic analyses have since revealed that the coelacanth''s genome evolves at an unusually slow rate compared to other vertebrates. _______ this slow rate of molecular change does not mean the species has remained biologically static; studies of coelacanth populations in different ocean basins show notable anatomical and physiological variation.', $lyceon_json$[{"key":"A","text":"Granted,"},{"key":"B","text":"In fact,"},{"key":"C","text":"Similarly,"},{"key":"D","text":"However,"}]$lyceon_json$::jsonb, 'D', NULL, E'"However" correctly signals a contrast between the expectation set up by the slow genomic evolution described in the second sentence and the clarification in the third sentence that the species has not remained biologically unchanged. The transition marks a shift from a finding that might suggest stasis to evidence of actual variation. "Granted" is a concessive transition that typically acknowledges a point before countering it, but the structure here does not concede the slow genomic rate as a lesser point — it corrects a potential misinterpretation of it. "In fact" would signal emphasis or confirmation of the preceding point, but the third sentence qualifies rather than reinforces the claim about slow genomic change. "Similarly" incorrectly implies that the anatomical variation parallels the slow genomic evolution, when the passage presents these as contrasting observations.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29XC1UO', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would Okoro (Text 2) most likely respond to Simmons''s findings in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AQBHA8', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every morning before the library opens, the head archivist ______ each display case and adjusts the lighting to protect the fragile documents from excessive exposure.', $lyceon_json$[{"key":"A","text":"inspect"},{"key":"B","text":"inspects"},{"key":"C","text":"are inspecting"},{"key":"D","text":"have inspected"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject is "the head archivist," a singular noun, and the sentence describes a habitual action ("every morning"), requiring the simple present tense. The singular present-tense form "inspects" agrees with the singular subject and matches the tense of "adjusts" later in the sentence. The base form "inspect" does not agree with a third-person singular subject. The progressive "are inspecting" uses a plural auxiliary that does not agree with the singular subject. The present perfect "have inspected" uses a plural auxiliary and shifts the tense away from the habitual present established by "every morning."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BHQEQS', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare manuscripts, which the library acquired from three private donors over the course of a decade, ______ one of the most valuable holdings in the entire university system.', $lyceon_json$[{"key":"A","text":"remain"},{"key":"B","text":"remains"},{"key":"C","text":"are remaining"},{"key":"D","text":"have remained"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "collection," which is singular despite the intervening prepositional phrase "of rare manuscripts" and the nonrestrictive clause "which the library acquired from three private donors over the course of a decade." Because the subject is singular, the verb must also be singular: "remains." The plural form "remain" incorrectly matches the verb to the nearby plural nouns "manuscripts" or "donors" rather than to the actual subject "collection." The progressive form "are remaining" uses a plural auxiliary and also mischaracterizes a permanent state as an ongoing action. The form "have remained" uses a plural auxiliary, again matching the verb to a nearby plural noun rather than to the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C12O3S', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Studies have shown that urban green spaces such as parks and community gardens can reduce air pollution and lower ambient temperatures in densely built neighborhoods. City planners in several major metropolitan areas have cited these findings when advocating for the expansion of green infrastructure. _______ the planners have also noted that green spaces can raise nearby property values, potentially displacing the lower-income residents who would benefit most from improved environmental conditions.', $lyceon_json$[{"key":"A","text":"Therefore,"},{"key":"B","text":"Likewise,"},{"key":"C","text":"At the same time,"},{"key":"D","text":"In particular,"}]$lyceon_json$::jsonb, 'C', NULL, E'"At the same time" correctly signals that the planners hold two concurrent but partially conflicting observations: they support green spaces for environmental benefits, yet they recognize that these same spaces can cause displacement of vulnerable residents. The transition captures this tension without implying outright contradiction. "Therefore" incorrectly suggests that the displacement concern is a logical consequence of advocating for green spaces, when the sentence actually introduces a complication that exists alongside the advocacy rather than resulting from it. "Likewise" incorrectly implies the final sentence reinforces the same point in a parallel manner, but the displacement concern runs counter to the environmental benefits. "In particular" incorrectly suggests the final sentence is a specific detail elaborating on the environmental benefits, when it actually introduces a separate socioeconomic concern.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CWLZP7', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the late nineteenth century, the boll weevil devastated cotton crops across the American South, forcing many farmers to abandon their reliance on a single cash crop. In Enterprise, Alabama, farmers began cultivating peanuts as an alternative, and the new crop proved so profitable that the town erected a monument to the boll weevil in 1919. _______ the pest that had initially threatened the region''s economy ultimately prompted an agricultural diversification that strengthened it.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"In other words,"},{"key":"C","text":"For example,"},{"key":"D","text":"On the other hand,"}]$lyceon_json$::jsonb, 'B', NULL, E'"In other words" is correct because the final sentence restates the idea conveyed by the preceding sentences in more general terms: the story of Enterprise and its monument illustrates that the destructive pest paradoxically benefited the region''s economy. "In addition" incorrectly signals that a new, supplementary point is being introduced, but the final sentence summarizes rather than adds new information. "For example" incorrectly implies the final sentence provides a specific illustration of a general claim, when it is actually the general restatement of the specific case already described. "On the other hand" incorrectly suggests the final sentence presents a contrasting perspective, but it reinforces the same point the passage has been building.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EW3Q1K', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The geologists who first mapped the underground river system beneath the limestone ______ were later credited with one of the most significant discoveries in regional hydrology.', $lyceon_json$[{"key":"A","text":"plateau, were"},{"key":"B","text":"plateau were"},{"key":"C","text":"plateau; were"},{"key":"D","text":"plateau. Were"}]$lyceon_json$::jsonb, 'B', NULL, E'The clause "who first mapped the underground river system beneath the limestone plateau" is a restrictive relative clause that identifies which geologists the sentence is about. Restrictive clauses are essential to the meaning of the sentence and must not be set off by commas. No punctuation should appear between the end of the restrictive clause and the main verb "were." Placing a comma before "were" incorrectly treats the clause as nonrestrictive and separates the subject from its verb. A semicolon cannot appear between a subject and its predicate within a single clause. A period after "plateau" would leave "Were later credited with one of the most significant discoveries in regional hydrology" as a fragment without a subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ILVGLP', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'A student claims that the city''s new bike-lane network has encouraged more residents to cycle to work. Which finding from the text, if accurate, would most directly support this claim?', E'In 2023, the city of Millbrook completed a 45-mile protected bike-lane network connecting major residential neighborhoods to the downtown business district. A transportation survey conducted in early 2024 found that 18 percent of downtown workers reported cycling as their primary commute method, up from 7 percent in a comparable 2022 survey. The city also recorded a 40 percent increase in bicycle sales at local retailers during the same period. However, public transit ridership declined by only 2 percent, and the number of cars entering downtown during morning rush hours remained essentially unchanged.', $lyceon_json$[{"key":"A","text":"The share of downtown workers who reported cycling as their primary commute method rose from 7 percent to 18 percent after the network was completed."},{"key":"B","text":"Public transit ridership declined by only 2 percent during the same period."},{"key":"C","text":"Bicycle sales at local retailers increased by 40 percent."},{"key":"D","text":"The number of cars entering downtown during morning rush hours remained essentially unchanged."}]$lyceon_json$::jsonb, 'A', NULL, E'The finding that the share of workers cycling to work rose from 7 percent to 18 percent after the bike-lane network was completed directly supports the claim that the network encouraged more cycling commuters. The finding about public transit ridership declining only slightly addresses transit usage, not cycling for commuting, and thus does not support the claim. The finding about increased bicycle sales is suggestive but indirect, since purchasing a bicycle does not necessarily mean using it for commuting. The finding about unchanged car traffic is irrelevant to the claim about cycling increases and, if anything, might seem to work against the idea that commuting patterns shifted.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2J6R2CX', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Anthropologist Yuki Tanaka has proposed that the emergence of permanent settlements in prehistoric Mesopotamia was driven less by agriculture than by the social demands of large-scale ritual activity. Conventional models hold that the shift from nomadic to sedentary life followed the domestication of cereal grains, which provided a reliable food surplus. Tanaka, however, points to archaeological evidence from Göbekli Tepe, where monumental stone structures built for communal ceremonies predate any signs of agricultural cultivation by several centuries. She argues that the labor coordination required to construct and maintain these ritual sites created sustained social bonds among previously dispersed groups, and that agriculture emerged as a secondary adaptation to feed the populations that had already begun to cluster around ceremonial centers.', $lyceon_json$[{"key":"A","text":"Permanent settlement in Mesopotamia may have been motivated primarily by communal ritual activity, with agriculture developing afterward to sustain the resulting populations."},{"key":"B","text":"Archaeological evidence from Göbekli Tepe proves that agriculture played no role in the development of early Mesopotamian settlements."},{"key":"C","text":"The domestication of cereal grains was a necessary precondition for the construction of monumental ritual structures in prehistoric Mesopotamia."},{"key":"D","text":"Tanaka's research confirms that nomadic groups in Mesopotamia abandoned ritual activity once they adopted agriculture."}]$lyceon_json$::jsonb, 'A', NULL, E'Tanaka''s argument is that ritual activity drove permanent settlement and that agriculture developed afterward to support populations already gathering at ceremonial sites, making the choice about communal ritual motivating settlement with agriculture following the best summary. The choice stating that Göbekli Tepe proves agriculture played no role overstates Tanaka''s position; she argues agriculture was a secondary adaptation, not that it was irrelevant to settlement development. The choice about grain domestication being a precondition for ritual structures reverses Tanaka''s argument, since she contends that the ritual structures came first and agriculture followed. The choice about nomadic groups abandoning ritual after adopting agriculture directly contradicts the passage, which presents ritual as the catalyst that preceded and prompted settled life.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JOVZLV', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The Hawaiian Islands formed over millions of years as the Pacific tectonic plate drifted over a stationary volcanic hotspot in the ocean floor. _______ the islands at the northwestern end of the chain, such as Kauai, are significantly older and more eroded than those at the southeastern end, such as the Big Island of Hawaii.', $lyceon_json$[{"key":"A","text":"In contrast,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"Consequently,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'C', NULL, E'"Consequently" is correct because the second sentence describes a direct result of the geological process outlined in the first: because the plate moved over a fixed hotspot, islands formed at different times, making the northwestern ones older and more eroded. "In contrast" incorrectly signals opposition between the two sentences, but the second sentence follows logically from the first rather than contradicting it. "Nevertheless" incorrectly implies that the age difference is surprising given the formation process, when it is in fact an expected outcome. "Meanwhile" incorrectly suggests two simultaneous but unrelated events, whereas the second sentence is a consequence of the first.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JPUJOW', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'The student wants to present a contrast between traditional and modern uses of fermentation while acknowledging a concern associated with the modern approach. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LD7DSV', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does "sound" most nearly mean?', E'Before investing in the startup, the venture capitalist reviewed the company''s business plan and concluded that the financial projections were sound, based on realistic market assumptions and conservative growth estimates.', $lyceon_json$[{"key":"A","text":"audible"},{"key":"B","text":"reliable"},{"key":"C","text":"loud"},{"key":"D","text":"rhythmic"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "reliable." In the passage, the venture capitalist determines that the financial projections are dependable and well-founded, supported by realistic assumptions and conservative estimates. "Audible" means capable of being heard, which produces an incoherent sentence when applied to financial projections. "Loud" refers to high volume or intensity of noise, which cannot logically describe the quality of a business plan''s projections. "Rhythmic" means having a regular, repeated pattern of beats or movement, which is nonsensical when substituted into a sentence about evaluating financial data.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LZN62E', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Helsinki have found that dogs can detect certain human diseases by smell with remarkable accuracy. In a 2024 trial, trained detection dogs correctly identified urine samples from patients with early-stage bladder cancer 95 percent of the time. The dogs were also able to distinguish cancerous samples from those affected by other urinary conditions, such as infections, which can produce similar odor profiles. The researchers suggest that dogs'' olfactory systems may detect volatile organic compounds released by cancer cells at concentrations too low for current laboratory instruments to measure reliably.', $lyceon_json$[{"key":"A","text":"Trained dogs can detect bladder cancer by smell with high accuracy, possibly sensing compounds that elude current laboratory technology."},{"key":"B","text":"Dogs have a stronger sense of smell than any laboratory instrument currently available."},{"key":"C","text":"Bladder cancer produces a distinctive odor that most mammals are capable of detecting."},{"key":"D","text":"Urinary infections and bladder cancer produce identical volatile organic compounds."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes dogs detecting bladder cancer with 95 percent accuracy and suggests they may sense compounds at concentrations too low for current instruments, making the choice about trained dogs detecting cancer with high accuracy and possibly sensing compounds that elude laboratory technology the best statement of the main idea. The choice claiming dogs have a stronger sense of smell than any instrument overgeneralizes the passage, which discusses only certain volatile organic compounds at low concentrations, not all olfactory tasks. The choice about most mammals detecting the odor extends the finding far beyond dogs, as the passage discusses only trained detection dogs. The choice stating that infections and cancer produce identical compounds contradicts the passage, which notes that dogs could distinguish cancerous samples from those affected by infections.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M13O7L', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'The student wants to emphasize the scientific significance of the axolotl''s biological abilities. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MM7YWS', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After conducting a yearlong survey of migratory patterns, the ornithological team reached a clear ______ the population of Arctic terns nesting along the northern coast had declined by nearly forty percent since 2015.', $lyceon_json$[{"key":"A","text":"conclusion: the"},{"key":"B","text":"conclusion, the"},{"key":"C","text":"conclusion the"},{"key":"D","text":"conclusion; and the"}]$lyceon_json$::jsonb, 'A', NULL, E'The second clause explains or elaborates on the "clear conclusion" mentioned in the first independent clause. A colon is the correct punctuation when an independent clause is followed by a statement that directly explains, illustrates, or specifies the preceding clause. Using a comma between two independent clauses creates a comma splice. Omitting punctuation entirely produces a fused sentence. A semicolon followed by "and" is redundant, since a semicolon alone or a comma with "and" would each be standard patterns for joining independent clauses, but combining both creates a nonstandard construction, and neither pattern fits as well as a colon given the explanatory relationship.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OP0B3D', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the third sentence in the text ("Some geologists ... to the surface")?', E'The discovery of high concentrations of iridium in geological layers dating to 66 million years ago provided crucial support for the hypothesis that an asteroid impact caused the mass extinction at the end of the Cretaceous period. Iridium is rare in Earth''s crust but abundant in extraterrestrial objects such as asteroids and comets. Some geologists initially proposed that volcanic activity could account for the iridium anomaly, since deep-Earth eruptions can also bring trace amounts of the element to the surface. Subsequent analysis, however, revealed that the iridium concentrations at the boundary layer far exceeded what any known volcanic event could produce.', $lyceon_json$[{"key":"A","text":"It provides the primary evidence supporting the asteroid impact hypothesis."},{"key":"B","text":"It introduces an alternative explanation that the passage goes on to address."},{"key":"C","text":"It summarizes the conclusion that the passage as a whole is building toward."},{"key":"D","text":"It describes the method geologists used to measure iridium concentrations in rock samples."}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is the choice stating that the third sentence introduces an alternative explanation that the passage goes on to address. The sentence presents the volcanic hypothesis as a competing account for the iridium anomaly, and the following sentence refutes it by noting that iridium concentrations exceeded what volcanic activity could produce. The choice about providing primary evidence for the asteroid hypothesis confuses the function of this sentence with that of the first sentence, which introduces the iridium discovery as support for the impact theory. The choice about summarizing the passage''s conclusion misidentifies the sentence''s role; the passage''s conclusion comes in the final sentence, which dismisses the volcanic explanation, while the third sentence introduces the challenge that conclusion addresses. The choice about measurement methods is unsupported; the sentence discusses a proposed explanation for the iridium anomaly, not the techniques used to detect or quantify it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PPFJHE', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Many people assume that memory works like a video recorder, faithfully capturing events as they unfold. However, cognitive psychologists have demonstrated that memory is reconstructive rather than reproductive. Each time a person recalls an event, the brain reassembles fragments of stored information, filling gaps with inferences and expectations. This process explains why eyewitnesses to the same event often produce contradictory accounts and why memories can become distorted through repeated retelling.', $lyceon_json$[{"key":"A","text":"It describes two competing theories of memory and evaluates which one has stronger experimental support."},{"key":"B","text":"It presents a series of experiments on memory and summarizes their collective findings."},{"key":"C","text":"It explains how memory works without addressing any common misconceptions."},{"key":"D","text":"It introduces a common misconception about memory and then presents the scientific understanding that corrects it."}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is the choice stating that the text introduces a common misconception and then presents the scientific understanding that corrects it. The passage opens with the widespread but incorrect belief that memory is like a video recorder, then uses "However" to pivot to the scientific finding that memory is reconstructive, explaining how the brain reassembles fragments rather than replaying recordings. The choice about two competing theories mischaracterizes the structure; the passage presents one misconception and one scientific correction, not two rival theories under evaluation. The choice about presenting experiments is inaccurate because the passage describes the findings of cognitive psychology generally without detailing specific experiments. The choice about explaining memory without addressing misconceptions overlooks the passage''s opening, which explicitly introduces the video-recorder assumption before correcting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R17ZWG', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Beneath the crumbling stone walls of the old fortress ______ a network of tunnels that served as escape routes during the medieval sieges of the region.', $lyceon_json$[{"key":"A","text":"lie"},{"key":"B","text":"lies"},{"key":"C","text":"is lying"},{"key":"D","text":"has lain"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence uses inverted word order: the subject "a network" follows the verb. Because "network" is singular, the verb must be the singular form "lies." The plural form "lie" would be correct only if the subject were plural. The progressive "is lying" changes the aspect to an ongoing action, but the sentence describes a permanent geographic fact that calls for the simple present. The present perfect "has lain" implies a change of state or a completed action, which does not fit the description of a fixed structural feature.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R4LVJL', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'The student wants to explain the original purpose of the Great Wall. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RL7D9U', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Economist Mariana Solano has challenged the widespread assumption that automation inevitably reduces total employment. Analyzing labor market data from twelve countries between 2010 and 2023, Solano found that industries adopting robotic automation did shed routine manual jobs, but these losses were largely offset by the creation of new positions in equipment maintenance, data analysis, and process supervision. Crucially, however, the new positions tended to require higher levels of technical training than the jobs they replaced. Solano argues that the real threat posed by automation is not mass unemployment but rather a widening skills gap that leaves workers without advanced training unable to transition into the emerging roles.', $lyceon_json$[{"key":"A","text":"Automation's primary economic risk is not job loss overall but a growing skills gap that disadvantages workers who lack advanced training."},{"key":"B","text":"Robotic automation has created more jobs than it has eliminated across all twelve countries Solano studied."},{"key":"C","text":"Workers displaced by automation can easily transition to new roles if they receive brief on-the-job training."},{"key":"D","text":"Solano's research demonstrates that routine manual jobs are no longer necessary in highly automated industries."}]$lyceon_json$::jsonb, 'A', NULL, E'Solano''s central argument is that automation does not cause mass unemployment but does create a skills gap, since the new jobs it generates require more advanced training than the ones it eliminates. The choice claiming automation has created more jobs than it eliminated misreads the passage, which states that losses were "largely offset" by new positions — not that new positions exceeded losses. The choice about workers transitioning easily with brief training contradicts the passage, which emphasizes that new positions require "higher levels of technical training" and that workers without such training are left behind. The choice about routine manual jobs no longer being necessary goes beyond the passage, which says these jobs were shed, not that they became unnecessary across entire industries.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SQ677R', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does "draft" most nearly mean?', E'After completing the initial draft of her dissertation, the doctoral candidate shared it with her advisor, who recommended substantial revisions to the theoretical framework and suggested incorporating more recent studies to support the central argument.', $lyceon_json$[{"key":"A","text":"breeze"},{"key":"B","text":"conscription"},{"key":"C","text":"version"},{"key":"D","text":"enrollment"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is "version." Here, "draft" refers to a preliminary version of a written document that is subject to revision, as confirmed by the advisor''s recommendation for substantial changes. "Breeze" refers to a current of air, which produces an incoherent phrase when substituted: an "initial breeze of her dissertation" is nonsensical. "Conscription" means compulsory military service, which has no connection to the academic writing context described in the passage. "Enrollment" refers to the process of registering or signing up, which cannot logically describe a preliminary written document shared with an advisor for revision.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SVZBLR', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'______ the effects of prolonged drought on regional agriculture, the environmental scientists published a comprehensive report recommending changes to current irrigation practices.', $lyceon_json$[{"key":"A","text":"Having studied"},{"key":"B","text":"Studying"},{"key":"C","text":"To have studied"},{"key":"D","text":"Being that they studied"}]$lyceon_json$::jsonb, 'A', NULL, E'The introductory participial phrase must logically modify the subject of the main clause, "the environmental scientists." The perfect participial "Having studied" correctly indicates that the scientists completed their study before publishing the report, establishing the proper temporal sequence. The present participle "Studying" implies that the studying and publishing happened simultaneously, which contradicts the logical sequence in which research precedes publication. The infinitive "To have studied" suggests purpose, but one does not publish a report for the purpose of having studied something; the studying is the cause, not the goal. The phrase "Being that they studied" is a nonstandard construction; standard written English uses "because" or a participial phrase rather than "being that" to express causation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
