INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UXVLQA', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'A botanist hypothesizes that mycorrhizal fungal networks allow mature trees to transfer nutrients to younger seedlings growing in shade. Which finding from the text, if valid, would most directly support this hypothesis?', E'Forest ecologist Lena Bergström investigated nutrient transfer among Douglas fir trees in an old-growth forest in British Columbia. Using isotopic carbon tracers injected into mature canopy trees, Bergström tracked the movement of labeled carbon through the soil over a six-month period. She found that seedlings growing within the root zones of mature trees contained significantly higher concentrations of the labeled carbon than seedlings growing in isolated clearings. Further analysis confirmed that the labeled carbon was present in mycorrhizal fungal filaments connecting the root systems of mature trees to those of nearby seedlings. Bergström also noted that seedlings receiving transferred carbon had 23 percent higher survival rates over the study period than isolated seedlings.', $lyceon_json$[{"key":"A","text":"Seedlings within the root zones of mature trees contained significantly higher concentrations of labeled carbon that was traced through mycorrhizal fungal filaments."},{"key":"B","text":"Seedlings receiving transferred carbon had 23 percent higher survival rates than isolated seedlings."},{"key":"C","text":"Bergström used isotopic carbon tracers injected into mature canopy trees."},{"key":"D","text":"Douglas fir trees in old-growth forests have extensive root systems that spread through the soil."}]$lyceon_json$::jsonb, 'A', NULL, E'The finding that labeled carbon from mature trees appeared in nearby seedlings via mycorrhizal fungal filaments directly supports the hypothesis that fungal networks enable nutrient transfer from mature trees to seedlings. The finding about higher survival rates demonstrates a consequence of the transfer but does not itself show that the transfer occurred through fungal networks, making it only partial support. The detail about using isotopic tracers describes the experimental method rather than providing evidence for the hypothesis. The claim about extensive root systems describes general tree anatomy and says nothing about nutrient transfer through fungal connections.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VC8Y74', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the museum''s newest exhibit on ancient Egyptian artifacts opened to the ______ hundreds of visitors lined up around the block to see the collection.', $lyceon_json$[{"key":"A","text":"public hundreds"},{"key":"B","text":"public, hundreds"},{"key":"C","text":"public; hundreds"},{"key":"D","text":"public. And hundreds"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence begins with the introductory dependent clause "When the museum''s newest exhibit on ancient Egyptian artifacts opened to the public," which must be followed by a comma before the main clause. Omitting all punctuation fuses the dependent clause into the main clause, creating a confusing run-on. A semicolon is used between two independent clauses, but the opening clause beginning with "When" is dependent and cannot stand alone. Placing a period after "public" and beginning a new sentence with "And hundreds" fragments the dependent clause from the main clause it modifies.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VI1IXB', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the text as a whole?', E'The creosote bush, native to the deserts of the southwestern United States, survives prolonged drought by coating its leaves with a waxy resin that minimizes water loss through evaporation. During the driest months, the plant can shed its smaller branches entirely, reducing its overall surface area and conserving moisture for its core root system.', $lyceon_json$[{"key":"A","text":"It describes how a desert plant conserves water through specific physical adaptations."},{"key":"B","text":"It argues that the creosote bush is the most resilient plant species in North American deserts."},{"key":"C","text":"It compares the creosote bush's survival strategies with those of other desert organisms."},{"key":"D","text":"It traces the evolutionary history of drought-resistant traits in desert vegetation."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the text describes how a desert plant conserves water through specific physical adaptations. The passage details two mechanisms the creosote bush uses: coating leaves with waxy resin to minimize evaporation and shedding branches to reduce surface area. The choice about the creosote bush being the most resilient species introduces a superlative claim the passage never makes; the text describes the plant''s strategies without ranking it against others. The choice about comparing survival strategies is inaccurate because the passage discusses only the creosote bush and references no other organisms. The choice about evolutionary history mischaracterizes the passage, which explains current adaptive mechanisms rather than tracing how those traits developed over time.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VN1ZY5', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Linguist Rahel Mengistu has studied how bilingual speakers of Amharic and English switch between languages during conversation. Previous research assumed that code-switching — alternating between two languages within a single utterance — occurred primarily when speakers lacked a word in one language and borrowed from the other. Mengistu''s analysis of recorded conversations among Ethiopian-American professionals, however, revealed a more complex pattern. Speakers consistently switched to English for technical workplace terminology, as expected, but they also switched to Amharic when expressing emotional evaluations, moral judgments, or appeals to shared cultural values — even when English equivalents were readily available. Mengistu argues that these switches are not evidence of lexical gaps but rather strategic acts through which speakers ________', $lyceon_json$[{"key":"A","text":"signal which cultural framework they consider most appropriate for interpreting a given statement."},{"key":"B","text":"conceal the content of sensitive conversations from monolingual English-speaking colleagues."},{"key":"C","text":"demonstrate their superior fluency in Amharic relative to other bilingual speakers in the group."},{"key":"D","text":"compensate for the limited emotional vocabulary available in the English language."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes speakers switching to Amharic for emotional evaluations, moral judgments, and cultural appeals even when English equivalents exist, which implies that the switches are strategic signals indicating which cultural lens should frame the statement. The choice about concealing content from monolingual colleagues introduces a motivation the passage does not discuss; the recorded conversations were among bilingual professionals, and secrecy is not mentioned. The choice about demonstrating superior fluency attributes a competitive motive unsupported by the passage, which frames the switching as communicative strategy rather than performance. The choice about compensating for limited English emotional vocabulary contradicts the passage, which explicitly states that English equivalents were readily available, meaning the switches were not driven by lexical gaps in English.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VQPR9R', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The novelist''s third ______ a sprawling epic set during the French Revolution ______ received mixed reviews from critics but became a bestseller within weeks of its release.', $lyceon_json$[{"key":"A","text":"book, a sprawling epic set during the French Revolution, received"},{"key":"B","text":"book a sprawling epic set during the French Revolution received"},{"key":"C","text":"book, a sprawling epic set during the French Revolution received"},{"key":"D","text":"book—a sprawling epic set during the French Revolution; received"}]$lyceon_json$::jsonb, 'A', NULL, E'The phrase "a sprawling epic set during the French Revolution" is an appositive that renames "the novelist''s third book." Appositives must be set off by a pair of commas when they are nonrestrictive. The correct choice places a comma both before and after the appositive, properly enclosing it and connecting the subject "book" to its verb "received." Omitting both commas fuses the appositive into the sentence without any boundary markers, making the sentence difficult to parse. Using only an opening comma but no closing comma leaves the appositive unclosed and merges it into the predicate. Using an em dash before the appositive and a semicolon after it creates mismatched punctuation; paired dashes or paired commas are needed, and a semicolon cannot separate a subject from its verb within a single clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WD9728', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Sleep scientists have long known that humans cycle through multiple stages of sleep each night, including periods of rapid eye movement (REM) sleep associated with vivid dreaming. Recent research has shown that the brain is far from inactive during non-REM sleep: it replays patterns of neural activity that occurred during the day''s learning experiences, a process believed to consolidate new memories. Disrupting non-REM sleep in laboratory subjects impairs their recall of information learned before sleeping, while leaving their ability to recall older, well-established memories intact. These findings suggest that non-REM sleep is particularly important for ________', $lyceon_json$[{"key":"A","text":"strengthening recently acquired memories rather than maintaining those already firmly stored."},{"key":"B","text":"erasing unnecessary memories so the brain can absorb new information the following day."},{"key":"C","text":"producing the vivid dreams that help individuals process emotional experiences."},{"key":"D","text":"restoring the body's physical energy levels after periods of sustained activity."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that disrupting non-REM sleep impairs recall of recently learned information but not older memories, which logically implies that non-REM sleep is especially important for consolidating new memories rather than maintaining established ones. The choice about erasing unnecessary memories introduces a function not discussed in the passage; the text describes memory consolidation, not memory deletion. The choice about vivid dreams misattributes a feature of REM sleep to non-REM sleep, since the passage explicitly associates vivid dreaming with REM sleep. The choice about restoring physical energy addresses a general function of sleep that the passage does not discuss at all.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-16"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-16","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
